const DailyView = memo(({
  currentTime,
  stats,
  dailySchedule,
  toggleScheduleItem,
  deleteScheduleItem,
  toggleSubTask,
  activePomodoroTask,
  startPomodoro,
  showCompletedTasks,
  setShowCompletedTasks,
