    const [expandedTasks, setExpandedTasks] = useState<Set<number>>(new Set());

    const toggleExpand = (id: number) => {
        setExpandedTasks(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    return (
    <div className="relative h-full overflow-y-auto pb-28 no-scrollbar">
      <div className="p-5 space-y-8">

        {/* Hero Section */}
        <div className="relative w-full h-64 rounded-[2.5rem] overflow-hidden shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] group">
            <img 
                src="https://i.pinimg.com/1200x/8f/86/a1/8f86a16b3271b758210d5208721c5124.jpg" 
                alt="Fantasy Sky" 
                className="absolute inset-0 w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700 filter brightness-75"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-[#0f0c29] via-transparent to-transparent opacity-90"></div>

            <div className="absolute inset-0 p-8 flex flex-col justify-between">
                <div className="flex justify-between items-start">
                   <div className="glass-panel px-4 py-1.5 rounded-full text-sm font-bold flex items-center gap-2 bg-black/30 border-white/20 backdrop-blur-md">
                      <Flame className="w-4 h-4 text-orange-500 fill-orange-500" />
                      <span className="font-serif">{stats.streak} أيام حماس</span>
                   </div>
                   <div className="glass-panel px-4 py-1.5 rounded-full text-sm font-bold flex items-center gap-2 bg-black/30 border-white/20 backdrop-blur-md">
                      <Award className="w-4 h-4 text-purple-400" />
                      <span className="font-serif">{stats.points} نقطة</span>
                   </div>
                </div>

                {/* Date on the left (visual left in RTL/LTR context) */}
                <div className="absolute bottom-8 left-8 text-left z-10" dir="ltr">
                   <p className="text-white font-serif text-3xl font-bold drop-shadow-[0_2px_10px_rgba(0,0,0,0.5)]">
                     {currentTime.toLocaleDateString('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' })}
                   </p>
                </div>
            </div>
        </div>

        {/* Schedule */}
        <div>
          <div className="flex items-center justify-between mb-4 px-2 pt-4 border-t border-white/5">
            <h3 className="text-2xl font-serif font-bold text-white flex items-center gap-2">
                <Calendar className="w-6 h-6 text-purple-400" />
                جدول اليوم
            </h3>
            <button onClick={() => setShowCompletedTasks(!showCompletedTasks)} className="flex items-center gap-1.5 text-xs text-purple-200 hover:text-white transition-colors px-4 py-2 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 font-serif">
                {showCompletedTasks ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                <span>{showCompletedTasks ? 'إخفاء المكتمل' : 'إظهار الكل'}</span>
            </button>
          </div>

          <div className="space-y-4">
             {dailySchedule.length === 0 && (
                <div className="text-center py-16 glass-card rounded-[2rem] border-dashed border-white/10 flex flex-col items-center justify-center">
                    <Calendar className="w-12 h-12 text-white/30 mb-4" />
                    <p className="text-gray-300 font-serif text-lg">جدولك صفحة بيضاء... <br/> ارسم يومك!</p>
                </div>
            )}

            {dailySchedule.map((item, index) => {
               if (!showCompletedTasks && item.completed) return null;

               const isNext = !item.completed && (index === 0 || dailySchedule.filter(i => showCompletedTasks || !i.completed)[index - 1]?.completed);
               const totalSubTasks = item.subTasks?.length || 0;
               const completedSubTasks = item.subTasks?.filter(st => st.completed).length || 0;
               const isExpanded = expandedTasks.has(item.id);

              return (
                <div
                  key={item.id}
                  className={`relative p-5 rounded-3xl border transition-all duration-500 group animate-slide-in ${
                    item.completed 
                      ? 'bg-black/40 border-white/5 opacity-60 grayscale-[0.5] translate-x-4'
                      : isNext
                      ? 'glass-card border-purple-500/40 shadow-[0_0_30px_rgba(168,85,247,0.1)] bg-gradient-to-e from-purple-900/20 to-transparent'
                      : 'glass-card border-white/5 hover:border-white/20'
