                       {item.subTasks && item.subTasks.length > 0 && !isExpanded && (
                           <button onClick={() => toggleExpand(item.id)} className="text-[10px] text-gray-500 flex items-center gap-1 mt-1 hover:text-purple-400 transition-colors">
                               {totalSubTasks} خطوات فرعية <ChevronDown className="w-3 h-3" />
                           </button>
                       )}

                      <div className="flex flex-wrap items-center gap-2 mt-4 opacity-80 group-hover:opacity-100 transition-opacity">
                           <span className={`px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
                                item.type === 'prayer' ? 'bg-green-500/10 border-green-500/20 text-green-300' :
                                item.type === 'habit' ? 'bg-blue-500/10 border-blue-500/20 text-blue-300' :
                                'bg-purple-500/10 border-purple-500/20 text-purple-300'
                            }`}>
                                {item.type === 'prayer' ? 'صلاة' : item.type === 'habit' ? 'عادة' : 'مهمة'}
                           </span>

