const ChatView = memo(({
  messages,
  suggestedTasks,
  confirmTask,
  confirmAllTasks,
  rejectTask,
  rejectAllTasks,
  isLoading,
  chatEndRef,
  inputRef,
  inputMessage,
  setInputMessage,
  handleSendMessage,
  attachedFile,
  setAttachedFile,
}: ChatViewProps) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Scroll to bottom whenever messages or suggested tasks change
    useEffect(() => {
        // Use a small timeout to ensure DOM is ready and layout is settled, providing a more robust scroll
        const timer = setTimeout(() => {
            chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }, 100);
        return () => clearTimeout(timer);
    }, [messages, suggestedTasks, isLoading, chatEndRef]);

    useEffect(() => {
        const textarea = inputRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            textarea.style.height = `${textarea.scrollHeight}px`;
        }
    }, [inputMessage, inputRef]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setAttachedFile({
            data: reader.result as string,
            mimeType: file.type,
          });
        };
        reader.readAsDataURL(file);
      }
    };

    return (
        <div className="flex flex-col h-full">
          <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-32 no-scrollbar">
            {messages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-[60vh] text-center">
                <div className="relative mb-8">
                     <div className="absolute inset-0 bg-purple-500 blur-[60px] opacity-20 animate-pulse"></div>
                     <div className="w-24 h-24 glass-card rounded-3xl flex items-center justify-center relative border border-white/10">
                        <Brain className="w-12 h-12 text-purple-300" />
                     </div>
                </div>
                <h3 className="text-3xl font-serif font-bold text-white mb-3">مساعدك الشخصي</h3>
                <p className="text-gray-400 max-w-xs font-serif text-lg">جاهز لتنظيم أفكارك وتحويلها لخطوات.</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-3xl p-5 shadow-lg ${
                  msg.role === 'user'
                    ? 'bg-gradient-to-br from-purple-600 to-indigo-600 text-white rounded-ts-md'
                    : 'glass-card text-gray-100 rounded-te-md border border-white/5'
                }`}>
                  {msg.role === 'ai' && (
                    <div className="flex items-center gap-2 mb-3 pb-2 border-b border-white/5">
                      <div className="p-1 bg-purple-500/20 rounded-lg">
                         <Brain className="w-4 h-4 text-purple-300" />
                      </div>
                      <span className="text-xs font-bold text-purple-300 font-serif">المساعد الذكي</span>
                    </div>
                  )}
                  {msg.attachment && (
                      <div className="mb-3 rounded-2xl overflow-hidden border border-white/10">
                        <img src={msg.attachment} alt="attachment" className="w-full max-h-64 object-cover" />
                      </div>
                  )}
                  <p className="whitespace-pre-wrap text-base leading-relaxed font-serif">{msg.text}</p>
                  <span className="text-[10px] opacity-50 mt-3 block text-start font-mono">
                    {msg.timestamp.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: true })}
                  </span>
                </div>
              </div>
            ))}

            {suggestedTasks.length > 0 && (
              <div className="glass-card rounded-3xl p-6 border border-purple-500/30 animate-slide-in relative overflow-hidden">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-purple-500 via-pink-500 to-purple-500"></div>
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-yellow-500/10 rounded-xl">
                         <Sparkles className="w-6 h-6 text-yellow-400" />
                    </div>
                    <div>
                        <span className="font-serif font-bold text-white text-lg block">اقتراحات ذكية</span>
                        <span className="text-xs text-gray-400">بناءً على محادثتنا</span>
                    </div>
                  </div>
                   <div className="flex items-center gap-2">
                    <button 
                        onClick={confirmAllTasks}
                        className="text-xs bg-green-500/10 text-green-400 hover:bg-green-500/20 border border-green-500/20 px-4 py-2 rounded-xl transition-all flex items-center gap-1.5 font-bold"
                    >
                        <Check className="w-3 h-3" />
                        قبول الكل
                    </button>
                    <button 
                        onClick={rejectAllTasks} 
                        className="text-xs bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/20 px-4 py-2 rounded-xl transition-all flex items-center gap-1.5 font-bold"
                    >
                        <X className="w-3 h-3" />
                        مسح
                    </button>
                  </div>
                </div>
                <div className="space-y-3">
                  {suggestedTasks.map(task => (
                    <div key={task.id} className="flex items-center justify-between p-4 bg-black/30 rounded-2xl border border-white/5 hover:border-purple-500/30 transition-colors group">
                      <div className="flex-1">
                        <p className="font-serif font-bold text-white text-base mb-1">{task.title}</p>
                        <div className="flex items-center gap-3">
                             <span className="px-2 py-0.5 bg-white/5 rounded-md text-[10px] text-gray-400 font-mono flex items-center gap-1"><Clock className="w-3 h-3" /> {ybFormatTo12Hour(task.time)}</span>
                             <span className="px-2 py-0.5 bg-white/5 rounded-md text-[10px] text-gray-400">{task.duration} دقيقة</span>
                        </div>
                        {task.subTasks && task.subTasks.length > 0 && (
                            <div className="mt-2 ps-3 border-s border-purple-500/20">
                                {task.subTasks.map((st, i) => (
                                    <div key={i} className="text-[10px] text-gray-400 flex items-center gap-1">
                                        <div className="w-1 h-1 rounded-full bg-purple-500"></div>
                                        {st.title}
                                    </div>
                                ))}
                            </div>
                        )}
                      </div>
                      <div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity self-start">
                        <button onClick={() => confirmTask(task.id)} className="p-2.5 rounded-xl bg-green-500/10 hover:bg-green-500 text-green-400 hover:text-white transition-all"><Check className="w-5 h-5" /></button>
                        <button onClick={() => rejectTask(task.id)} className="p-2.5 rounded-xl bg-red-500/10 hover:bg-red-500 text-red-400 hover:text-white transition-all"><X className="w-5 h-5" /></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {isLoading && (
              <div className="flex justify-start">
                <div className="glass-card rounded-2xl p-4 rounded-te-sm flex items-center gap-3">
                    <div className="w-5 h-5 border-2 border-purple-400 border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-sm text-purple-200 font-serif animate-pulse">جاري التفكير...</span>
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 glass-panel rounded-t-[2.5rem] border-t border-white/10 bg-[#0f0c29]/80 backdrop-blur-xl">
             {attachedFile && (
                <div className="mb-4 p-3 bg-white/5 rounded-2xl flex items-center justify-between border border-white/10 mx-2">
                    <div className="flex items-center gap-3">
                        <div className="w-12 h-12 rounded-xl overflow-hidden bg-black border border-white/10">
                            <img src={attachedFile.data} className="w-full h-full object-cover" alt="Attached" />
                        </div>
                        <div>
                             <span className="text-sm font-bold text-white block">صورة مرفقة</span>
                             <span className="text-xs text-gray-400">جاهزة للإرسال</span>
                        </div>
                    </div>
                    <button onClick={() => setAttachedFile(null)} className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-4 h-4" />
                    </button>
                </div>
             )}

             <div className="flex items-end gap-2">
                <button onClick={() => fileInputRef.current?.click()} className="p-3 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/5">
                    <Paperclip className="w-5 h-5" />
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />

                <div className="flex-1 relative">
                    <textarea
                        ref={inputRef}
                        value={inputMessage}
                        onChange={(e) => setInputMessage(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                handleSendMessage();
                            }
                        }}
                        placeholder="تحدث مع مدربك..."
                        className="w-full bg-white/5 border border-white/10 rounded-2xl py-3 px-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500/50 focus:bg-white/10 resize-none max-h-32 min-h-[50px] font-serif"
                        rows={1}
                    />
                </div>

                <button 
                    onClick={() => handleSendMessage()} 
                    disabled={(!inputMessage.trim() && !attachedFile) || isLoading}
                    className={`p-3 rounded-full transition-all ${(!inputMessage.trim() && !attachedFile) || isLoading ? 'bg-white/5 text-gray-600 cursor-not-allowed' : 'bg-purple-600 hover:bg-purple-500 text-white shadow-[0_0_15px_rgba(147,51,234,0.3)]'}`}
                >
                   <Play className="w-5 h-5 transform scale-x-[-1]" />
                </button>
             </div>
             <div className="flex gap-2 mt-3 overflow-x-auto pb-2 no-scrollbar">
                {['راجع يومي', 'اقترح لي مهام', 'حمسني!'].map((quick, idx) => (
                    <button key={idx} onClick={() => { setInputMessage(quick); setTimeout(() => handleSendMessage(quick), 100); }} className="px-4 py-2 glass-card border-white/5 rounded-xl text-xs text-gray-300 hover:text-white hover:border-purple-500/30 whitespace-nowrap transition-all">
                        {quick}
                    </button>
                ))}
            </div>
          </div>
        </div>
    );
});

