const AuthView = memo(({ onLogin, addNotification }: AuthViewProps) => {
    const [isSignUp, setIsSignUp] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [showForgotPassword, setShowForgotPassword] = useState(false);

    const handleResetPassword = async () => {
        if(!email) {
             addNotification("من فضلك أدخل بريدك الإلكتروني أولاً", "warning");
             return;
        }
        setIsLoading(true);
        try {
            const { error } = await supabase.auth.resetPasswordForEmail(email);
            if (error) throw error;
            addNotification("تم إرسال رابط إعادة تعيين كلمة المرور لبريدك الإلكتروني", "success");
            setShowForgotPassword(false);
        } catch (error: any) {
             addNotification(mapAuthError(error), "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleAuth = async () => {
        if (!email || !password) {
            addNotification("من فضلك أدخل البريد الإلكتروني وكلمة المرور", "warning");
            return;
        }

        setIsLoading(true);

        try {
            if (isSignUp) {
                if (!name) {
                     addNotification("من فضلك أدخل اسمك", "warning");
                     setIsLoading(false);
                     return;
                }

                const { data, error } = await supabase.auth.signUp({
                    email,
                    password,
                    options: {
                        data: {
                            name,
                            // Wake and Sleep time will be set in onboarding
                        }
                    }
                });

                if (error) throw error;

                if (data.user) {
                    await supabase.from('profiles').upsert({
                        id: data.user.id,
                        name,
                    });
                }

                if (data.user && !data.session) {
                     addNotification("تم إنشاء الحساب! يرجى تأكيد البريد الإلكتروني للدخول 📧", "success");
                     setIsLoading(false);
                     return; 
                }

                addNotification("تم إنشاء الحساب بنجاح! 🚀", "success");
            } else {
                const { error } = await supabase.auth.signInWithPassword({
                    email,
                    password
                });
                if (error) throw error;
                addNotification("مرحباً بعودتك! 👋", "success");
            }
            // Trigger login success callback immediately
            onLogin(); 
        } catch (error: any) {
            addNotification(mapAuthError(error), "error");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#0f0c29]">
             <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1519681393798-3828fb4090bb?q=80&w=2940')] bg-cover opacity-20"></div>
             <div className="glass-card w-full max-w-md p-8 rounded-[2.5rem] border border-white/10 relative shadow-2xl animate-in zoom-in duration-300">
                <div className="text-center mb-8">
                     <div className="w-16 h-16 bg-gradient-to-br from-purple-600 to-blue-600 rounded-2xl mx-auto flex items-center justify-center shadow-lg transform rotate-3 mb-4">
                         <Brain className="w-8 h-8 text-white" />
                     </div>
                     <h2 className="text-3xl font-serif font-bold text-white mb-2">
                        {showForgotPassword ? 'نسيت كلمة المرور؟' : (isSignUp ? 'حساب جديد' : 'تسجيل الدخول')}
                     </h2>
                     <p className="text-gray-400 font-serif text-sm">
                        {showForgotPassword ? 'أدخل بريدك لاستعادة الحساب' : 'ابدأ رحلتك نحو الإنتاجية والتركيز'}
                     </p>
                </div>

                <div className="space-y-4">
                    {!showForgotPassword && isSignUp && (
                        <div className="relative animate-slide-in">
                            <User className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                            <input 
                                type="text" 
                                placeholder="الاسم" 
                                value={name}
                                onChange={e => setName(e.target.value)}
                                className="w-full bg-black/30 border border-white/20 rounded-xl p-4 pr-12 text-white placeholder-gray-500 focus:border-purple-500 outline-none transition-all"
                            />
                        </div>
                    )}

                    <div className="relative">
                        <Mail className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                         <input 
                            type="email" 
                            placeholder="البريد الإلكتروني" 
                            value={email}
                            onChange={e => setEmail(e.target.value)}
                            className="w-full bg-black/30 border border-white/20 rounded-xl p-4 pr-12 text-white placeholder-gray-500 focus:border-purple-500 outline-none transition-all"
                        />
                    </div>

                    {!showForgotPassword && (
                        <div className="relative">
                            <Lock className="absolute top-1/2 -translate-y-1/2 right-4 w-5 h-5 text-gray-400" />
                             <input 
                                type="password" 
                                placeholder="كلمة المرور" 
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                className="w-full bg-black/30 border border-white/20 rounded-xl p-4 pr-12 text-white placeholder-gray-500 focus:border-purple-500 outline-none transition-all"
                            />
                        </div>
                    )}

                    {!showForgotPassword ? (
                        <button 
                            onClick={handleAuth}
                            disabled={isLoading}
                            className="w-full py-4 bg-gradient-to-r from-purple-600 to-pink-600 text-white font-bold rounded-xl shadow-lg hover:shadow-purple-500/50 transition-all transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {isLoading ? <Activity className="w-6 h-6 animate-spin mx-auto" /> : (isSignUp ? 'إنشاء حساب' : 'دخول')}
                        </button>
                    ) : (
                        <button 
                            onClick={handleResetPassword}
                            disabled={isLoading}
                            className="w-full py-4 bg-gradient-to-r from-yellow-600 to-orange-600 text-white font-bold rounded-xl shadow-lg hover:shadow-yellow-500/50 transition-all transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {isLoading ? <Activity className="w-6 h-6 animate-spin mx-auto" /> : 'إرسال رابط التعيين'}
                        </button>
                    )}

                    <div className="text-center pt-2 flex flex-col gap-2">
                        {showForgotPassword ? (
                             <button 
                                onClick={() => setShowForgotPassword(false)}
                                className="text-sm text-gray-400 hover:text-white transition-colors"
                            >
                                العودة لتسجيل الدخول
                            </button>
                        ) : (
                            <>
                                <button 
                                    onClick={() => setIsSignUp(!isSignUp)}
                                    className="text-sm text-gray-400 hover:text-white transition-colors underline decoration-dotted"
                                >
                                    {isSignUp ? 'لديك حساب بالفعل؟ سجل دخولك' : 'مستخدم جديد؟ أنشئ حساباً'}
                                </button>
                                {!isSignUp && (
                                    <button 
                                        onClick={() => setShowForgotPassword(true)}
                                        className="text-xs text-purple-400 hover:text-purple-300 transition-colors"
                                    >
                                        نسيت كلمة المرور؟
                                    </button>
                                )}
                            </>
                        )}
                    </div>
                </div>
             </div>
        </div>
    );
});

