// --- Helpers ---

const ybFormatTo12Hour = (timeString: string): string => {
  if (!timeString || !timeString.includes(':')) return timeString;
  const [hour, minute] = timeString.split(':').map(Number);
  const ampm = hour >= 12 ? 'م' : 'ص';
  let hour12 = hour % 12;
  if (hour12 === 0) hour12 = 12;
  return `${hour12.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')} ${ampm}`;
};

const mapAuthError = (error: any): string => {
    const msg = error.message || '';
    if (msg.includes('Invalid login credentials')) return 'البريد الإلكتروني أو كلمة المرور غير صحيحة';
    if (msg.includes('User not found')) return 'هذا الحساب غير مسجل لدينا، يرجى إنشاء حساب جديد';
    if (msg.includes('Password should be')) return 'كلمة المرور ضعيفة جدًا، يرجى اختيار كلمة أقوى';
    if (msg.includes('Email not confirmed')) return 'يرجى تأكيد البريد الإلكتروني أولاً';
    if (msg.includes('already registered')) return 'هذا البريد مسجل بالفعل، حاول تسجيل الدخول';
    return msg;
};

