                                className="w-full p-5 flex items-center justify-between text-white transition-colors"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-white/10 backdrop-blur-md rounded-xl border border-white/20 shadow-inner">
                                       <Icon className="w-6 h-6 text-white drop-shadow-md" />
                                    </div>
                                    <span className="font-serif text-xl font-bold">{category.name}</span>
                                </div>
                                <div className={`p-2 rounded-full bg-white/5 backdrop-blur-sm transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                                     <ChevronDown className="w-5 h-5 text-white" />
                                </div>
                            </button>

                            {isOpen && (
                                <div className="p-5 pt-0 animate-slide-in">
                                    <div className="grid grid-cols-1 gap-3">
                                        {category.tasks.map(task => (
                                            <div key={task.id} className="flex items-center gap-3 p-3 bg-black/40 backdrop-blur-md rounded-xl border border-white/10 hover:bg-white/10 transition-colors">
                                                <span className="text-2xl filter drop-shadow-sm">{task.icon}</span>
                                                <div className="flex-1">
                                                    <p className="font-serif font-medium text-white">{task.title}</p>
                                                    <p className="text-xs text-gray-400">{task.duration} دقيقة</p>
                                                </div>
                                                <button 
                                                    onClick={() => onAddTask(task)}
                                                    className="p-2 text-gray-300 hover:text-white bg-white/5 hover:bg-purple-500 rounded-full transition-all"
                                                >
                                                    <PlusCircle className="w-5 h-5" />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
            </div>
        </div>
    );
});

const DailyView = memo(({
  currentTime,
  stats,
  dailySchedule,
  toggleScheduleItem,
  deleteScheduleItem,
  toggleSubTask,
  activePomodoroTask,
  startPomodoro,
  showCompletedTasks,
  setShowCompletedTasks,
  queryTaskDetails,
  taskCategories,
  handleAddTaskFromTemplate,
  setReminderTask,
  onAddTask,
  onEditTask,
}: DailyViewProps) => {
    const [expandedTasks, setExpandedTasks] = useState<Set<number>>(new Set());

    const toggleExpand = (id: number) => {
        setExpandedTasks(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    return (
    <div className="relative h-full overflow-y-auto pb-28 no-scrollbar">
      <div className="p-5 space-y-8">

        {/* Hero Section */}
        <div className="relative w-full h-64 rounded-[2.5rem] overflow-hidden shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] group">
            <img 
                src="https://i.pinimg.com/1200x/8f/86/a1/8f86a16b3271b758210d5208721c5124.jpg" 
                alt="Fantasy Sky" 
                className="absolute inset-0 w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700 filter brightness-75"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-[#0f0c29] via-transparent to-transparent opacity-90"></div>

            <div className="absolute inset-0 p-8 flex flex-col justify-between">
                <div className="flex justify-between items-start">
                   <div className="glass-panel px-4 py-1.5 rounded-full text-sm font-bold flex items-center gap-2 bg-black/30 border-white/20 backdrop-blur-md">
                      <Flame className="w-4 h-4 text-orange-500 fill-orange-500" />
                      <span className="font-serif">{stats.streak} أيام حماس</span>
                   </div>
                   <div className="glass-panel px-4 py-1.5 rounded-full text-sm font-bold flex items-center gap-2 bg-black/30 border-white/20 backdrop-blur-md">
                      <Award className="w-4 h-4 text-purple-400" />
                      <span className="font-serif">{stats.points} نقطة</span>
                   </div>
                </div>

                {/* Date on the left (visual left in RTL/LTR context) */}
                <div className="absolute bottom-8 left-8 text-left z-10" dir="ltr">
                   <p className="text-white font-serif text-3xl font-bold drop-shadow-[0_2px_10px_rgba(0,0,0,0.5)]">
                     {currentTime.toLocaleDateString('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' })}
                   </p>
                </div>
            </div>
        </div>

        {/* Schedule */}
        <div>
          <div className="flex items-center justify-between mb-4 px-2 pt-4 border-t border-white/5">
            <h3 className="text-2xl font-serif font-bold text-white flex items-center gap-2">
                <Calendar className="w-6 h-6 text-purple-400" />
                جدول اليوم
            </h3>
            <button onClick={() => setShowCompletedTasks(!showCompletedTasks)} className="flex items-center gap-1.5 text-xs text-purple-200 hover:text-white transition-colors px-4 py-2 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 font-serif">
                {showCompletedTasks ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                <span>{showCompletedTasks ? 'إخفاء المكتمل' : 'إظهار الكل'}</span>
            </button>
          </div>

          <div className="space-y-4">
             {dailySchedule.length === 0 && (
                <div className="text-center py-16 glass-card rounded-[2rem] border-dashed border-white/10 flex flex-col items-center justify-center">
                    <Calendar className="w-12 h-12 text-white/30 mb-4" />
                    <p className="text-gray-300 font-serif text-lg">جدولك صفحة بيضاء... <br/> ارسم يومك!</p>
                </div>
            )}

            {dailySchedule.map((item, index) => {
               if (!showCompletedTasks && item.completed) return null;

               const isNext = !item.completed && (index === 0 || dailySchedule.filter(i => showCompletedTasks || !i.completed)[index - 1]?.completed);
               const totalSubTasks = item.subTasks?.length || 0;
               const completedSubTasks = item.subTasks?.filter(st => st.completed).length || 0;
               const isExpanded = expandedTasks.has(item.id);

              return (
                <div
                  key={item.id}
                  className={`relative p-5 rounded-3xl border transition-all duration-500 group animate-slide-in ${
                    item.completed 
                      ? 'bg-black/40 border-white/5 opacity-60 grayscale-[0.5] translate-x-4'
                      : isNext
                      ? 'glass-card border-purple-500/40 shadow-[0_0_30px_rgba(168,85,247,0.1)] bg-gradient-to-e from-purple-900/20 to-transparent'
                      : 'glass-card border-white/5 hover:border-white/20'
                  }`}
                >
                   {isNext && !item.completed && <div className="absolute -start-[1px] top-6 bottom-6 w-1 bg-gradient-to-b from-purple-400 to-pink-400 rounded-e-full shadow-[0_0_15px_rgba(192,38,211,0.5)] animate-pulse"></div>}

                  <div className="flex items-start gap-4">
                    <button
                      onClick={() => toggleScheduleItem(item.id)}
                      className={`mt-1.5 w-7 h-7 rounded-xl border-2 flex items-center justify-center flex-shrink-0 transition-all duration-300 ${
                        item.completed 
                          ? 'bg-gradient-to-br from-green-400 to-emerald-600 border-transparent shadow-[0_0_15px_rgba(34,197,94,0.4)]'
                          : isNext
                          ? 'border-purple-400 hover:bg-purple-400/20'
                          : 'border-gray-600 hover:border-gray-400'
                      }`}
                    >
                      {item.completed && <Check className="w-4 h-4 text-white stroke-[3]" />}
                    </button>

                    <div className="flex-1 min-w-0 pt-0.5">
                      <div className="flex items-center gap-2 mb-1.5" onClick={() => toggleExpand(item.id)}>
                        <span className={`text-sm font-mono font-bold tracking-wider ${isNext ? 'text-purple-300' : 'text-gray-500'}`}>{ybFormatTo12Hour(item.time)}</span>
                        {item.duration > 0 && <span className="px-2 py-0.5 rounded-md bg-white/5 text-[10px] text-gray-400 border border-white/5">{item.duration} د</span>}
                      </div>

                      <div className="cursor-pointer" onClick={() => toggleExpand(item.id)}>
                          <p className={`font-serif font-bold text-xl mb-1.5 leading-tight ${item.completed ? 'text-gray-500 line-through decoration-gray-600 decoration-2' : 'text-white'}`}>
                            {item.title}
                          </p>
                          {item.description && <p className="text-sm text-gray-400 mb-2 font-light line-clamp-2">{item.description}</p>}
                      </div>

                      {item.subTasks && item.subTasks.length > 0 && (
                          <div className={`mt-3 space-y-2 ps-4 border-s border-white/10 ms-1 transition-all duration-300 overflow-hidden ${isExpanded ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
                             <div className="flex items-center justify-between mb-1">
                                <span className="text-[10px] font-bold text-gray-400">الخطوات ({completedSubTasks}/{totalSubTasks})</span>
                             </div>
                             {item.subTasks.map(subTask => (
                                <div key={subTask.id} className="flex items-center gap-2 group/sub cursor-pointer" onClick={() => toggleSubTask(item.id, subTask.id)}>
                                    <div className={`w-3 h-3 rounded border flex-shrink-0 transition-all ${subTask.completed ? 'bg-green-500 border-green-500' : 'border-gray-600 group-hover/sub:border-white'}`}></div>
                                    <span className={`text-sm font-serif ${subTask.completed ? 'text-gray-500 line-through' : 'text-gray-300 group-hover/sub:text-white'}`}>
                                        {subTask.title}
                                    </span>
                                </div>
                            ))}
                          </div>
                      )}

                       {item.subTasks && item.subTasks.length > 0 && !isExpanded && (
                           <button onClick={() => toggleExpand(item.id)} className="text-[10px] text-gray-500 flex items-center gap-1 mt-1 hover:text-purple-400 transition-colors">
                               {totalSubTasks} خطوات فرعية <ChevronDown className="w-3 h-3" />
                           </button>
                       )}

                      <div className="flex flex-wrap items-center gap-2 mt-4 opacity-80 group-hover:opacity-100 transition-opacity">
                           <span className={`px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
                                item.type === 'prayer' ? 'bg-green-500/10 border-green-500/20 text-green-300' :
                                item.type === 'habit' ? 'bg-blue-500/10 border-blue-500/20 text-blue-300' :
                                'bg-purple-500/10 border-purple-500/20 text-purple-300'
                            }`}>
                                {item.type === 'prayer' ? 'صلاة' : item.type === 'habit' ? 'عادة' : 'مهمة'}
                           </span>

                           <div className="flex items-center gap-1 me-auto">
                                <button onClick={() => queryTaskDetails(item)} className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors"><HelpCircle className="w-4 h-4" /></button>
                                <button onClick={() => onEditTask(item)} className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors"><Pencil className="w-4 h-4" /></button>
                                <button onClick={() => setReminderTask(item)} className={`p-2 rounded-full hover:bg-white/10 transition-colors ${item.reminderMinutes ? 'text-yellow-400' : 'text-gray-400'}`}><Bell className="w-4 h-4" /></button>
                                <button onClick={() => deleteScheduleItem(item.id)} className="p-2 text-gray-400 hover:text-red-400 hover:bg-red-500/10 rounded-full transition-colors"><Trash2 className="w-4 h-4" /></button>
                           </div>
                      </div>
                    </div>

                     <div className="self-center flex-shrink-0 ms-1">
                      {activePomodoroTask?.id === item.id ? (
                        <div className="relative">
                            <div className="absolute inset-0 bg-purple-500 blur-xl opacity-40 animate-pulse"></div>
                            <div className="relative bg-black/50 p-2.5 rounded-full border border-purple-500 shadow-[0_0_15px_rgba(168,85,247,0.3)]">
                                <Activity className="w-6 h-6 text-purple-300 animate-spin-slow" />
                            </div>
                        </div>
                      ) : (!item.completed && item.type === 'task' ? (
                        <button
                          onClick={() => startPomodoro(item)}
                          className="p-3.5 rounded-full bg-white/5 hover:bg-purple-600/30 border border-white/10 hover:border-purple-500/50 transition-all group active:scale-95"
                        >
                          <Play className="w-6 h-6 text-gray-400 group-hover:text-white group-hover:fill-white/20 transition-colors transform scale-x-[-1]" />
                        </button>
                      ) : null)}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <CoreHabitsView categories={taskCategories} onAddTask={handleAddTaskFromTemplate} />

      </div>

      {/* Floating Action Button */}
      <button
        onClick={onAddTask}
        className="fixed bottom-24 start-6 w-16 h-16 bg-gradient-to-tr from-purple-600 to-pink-600 text-white rounded-full shadow-[0_0_30px_rgba(236,72,153,0.4)] hover:scale-110 hover:rotate-90 transition-all z-30 flex items-center justify-center border border-white/20"
        aria-label="إضافة مهمة جديدة"
      >
        <Plus className="w-8 h-8" />
      </button>
    </div>
  );
});

const ChatView = memo(({
  messages,
  suggestedTasks,
  confirmTask,
  confirmAllTasks,
  rejectTask,
  rejectAllTasks,
  isLoading,
  chatEndRef,
  inputRef,
  inputMessage,
  setInputMessage,
  handleSendMessage,
  attachedFile,
  setAttachedFile,
}: ChatViewProps) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Scroll to bottom whenever messages or suggested tasks change
    useEffect(() => {
        // Use a small timeout to ensure DOM is ready and layout is settled, providing a more robust scroll
        const timer = setTimeout(() => {
            chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }, 100);
        return () => clearTimeout(timer);
    }, [messages, suggestedTasks, isLoading, chatEndRef]);

    useEffect(() => {
        const textarea = inputRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            textarea.style.height = `${textarea.scrollHeight}px`;
        }
    }, [inputMessage, inputRef]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setAttachedFile({
            data: reader.result as string,
            mimeType: file.type,
          });
        };
        reader.readAsDataURL(file);
      }
    };

    return (
        <div className="flex flex-col h-full">
          <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-32 no-scrollbar">
            {messages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-[60vh] text-center">
                <div className="relative mb-8">
                     <div className="absolute inset-0 bg-purple-500 blur-[60px] opacity-20 animate-pulse"></div>
                     <div className="w-24 h-24 glass-card rounded-3xl flex items-center justify-center relative border border-white/10">
                        <Brain className="w-12 h-12 text-purple-300" />
                     </div>
                </div>
                <h3 className="text-3xl font-serif font-bold text-white mb-3">مساعدك الشخصي</h3>
                <p className="text-gray-400 max-w-xs font-serif text-lg">جاهز لتنظيم أفكارك وتحويلها لخطوات.</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-3xl p-5 shadow-lg ${
                  msg.role === 'user'
                    ? 'bg-gradient-to-br from-purple-600 to-indigo-600 text-white rounded-ts-md'
                    : 'glass-card text-gray-100 rounded-te-md border border-white/5'
                }`}>
                  {msg.role === 'ai' && (
                    <div className="flex items-center gap-2 mb-3 pb-2 border-b border-white/5">
                      <div className="p-1 bg-purple-500/20 rounded-lg">
                         <Brain className="w-4 h-4 text-purple-300" />
                      </div>
                      <span className="text-xs font-bold text-purple-300 font-serif">المساعد الذكي</span>
                    </div>
                  )}
                  {msg.attachment && (
                      <div className="mb-3 rounded-2xl overflow-hidden border border-white/10">
                        <img src={msg.attachment} alt="attachment" className="w-full max-h-64 object-cover" />
                      </div>
                  )}
                  <p className="whitespace-pre-wrap text-base leading-relaxed font-serif">{msg.text}</p>
                  <span className="text-[10px] opacity-50 mt-3 block text-start font-mono">
                    {msg.timestamp.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: true })}
                  </span>
                </div>
              </div>
            ))}

            {suggestedTasks.length > 0 && (
              <div className="glass-card rounded-3xl p-6 border border-purple-500/30 animate-slide-in relative overflow-hidden">
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-purple-500 via-pink-500 to-purple-500"></div>
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-yellow-500/10 rounded-xl">
                         <Sparkles className="w-6 h-6 text-yellow-400" />
                    </div>
                    <div>
                        <span className="font-serif font-bold text-white text-lg block">اقتراحات ذكية</span>
                        <span className="text-xs text-gray-400">بناءً على محادثتنا</span>
                    </div>
                  </div>
                   <div className="flex items-center gap-2">
                    <button 
                        onClick={confirmAllTasks}
                        className="text-xs bg-green-500/10 text-green-400 hover:bg-green-500/20 border border-green-500/20 px-4 py-2 rounded-xl transition-all flex items-center gap-1.5 font-bold"
                    >
                        <Check className="w-3 h-3" />
                        قبول الكل
                    </button>
                    <button 
                        onClick={rejectAllTasks} 
                        className="text-xs bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/20 px-4 py-2 rounded-xl transition-all flex items-center gap-1.5 font-bold"
                    >
                        <X className="w-3 h-3" />
                        مسح
                    </button>
                  </div>
                </div>
                <div className="space-y-3">
                  {suggestedTasks.map(task => (
                    <div key={task.id} className="flex items-center justify-between p-4 bg-black/30 rounded-2xl border border-white/5 hover:border-purple-500/30 transition-colors group">
                      <div className="flex-1">
                        <p className="font-serif font-bold text-white text-base mb-1">{task.title}</p>
                        <div className="flex items-center gap-3">
                             <span className="px-2 py-0.5 bg-white/5 rounded-md text-[10px] text-gray-400 font-mono flex items-center gap-1"><Clock className="w-3 h-3" /> {ybFormatTo12Hour(task.time)}</span>
                             <span className="px-2 py-0.5 bg-white/5 rounded-md text-[10px] text-gray-400">{task.duration} دقيقة</span>
                        </div>
                        {task.subTasks && task.subTasks.length > 0 && (
                            <div className="mt-2 ps-3 border-s border-purple-500/20">
                                {task.subTasks.map((st, i) => (
                                    <div key={i} className="text-[10px] text-gray-400 flex items-center gap-1">
                                        <div className="w-1 h-1 rounded-full bg-purple-500"></div>
                                        {st.title}
                                    </div>
                                ))}
                            </div>
                        )}
                      </div>
                      <div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity self-start">
                        <button onClick={() => confirmTask(task.id)} className="p-2.5 rounded-xl bg-green-500/10 hover:bg-green-500 text-green-400 hover:text-white transition-all"><Check className="w-5 h-5" /></button>
                        <button onClick={() => rejectTask(task.id)} className="p-2.5 rounded-xl bg-red-500/10 hover:bg-red-500 text-red-400 hover:text-white transition-all"><X className="w-5 h-5" /></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {isLoading && (
              <div className="flex justify-start">
                <div className="glass-card rounded-2xl p-4 rounded-te-sm flex items-center gap-3">
                    <div className="w-5 h-5 border-2 border-purple-400 border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-sm text-purple-200 font-serif animate-pulse">جاري التفكير...</span>
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 glass-panel rounded-t-[2.5rem] border-t border-white/10 bg-[#0f0c29]/80 backdrop-blur-xl">
             {attachedFile && (
                <div className="mb-4 p-3 bg-white/5 rounded-2xl flex items-center justify-between border border-white/10 mx-2">
                    <div className="flex items-center gap-3">
                        <div className="w-12 h-12 rounded-xl overflow-hidden bg-black border border-white/10">
                            <img src={attachedFile.data} className="w-full h-full object-cover" alt="Attached" />
                        </div>
                        <div>
                             <span className="text-sm font-bold text-white block">صورة مرفقة</span>
                             <span className="text-xs text-gray-400">جاهزة للإرسال</span>
                        </div>
                    </div>
                    <button onClick={() => setAttachedFile(null)} className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-4 h-4" />
                    </button>
                </div>
             )}

             <div className="flex items-end gap-2">
                <button onClick={() => fileInputRef.current?.click()} className="p-3 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/5">
                    <Paperclip className="w-5 h-5" />
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />

                <div className="flex-1 relative">
                    <textarea
                        ref={inputRef}
                        value={inputMessage}
                        onChange={(e) => setInputMessage(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                handleSendMessage();
                            }
                        }}
                        placeholder="تحدث مع مدربك..."
                        className="w-full bg-white/5 border border-white/10 rounded-2xl py-3 px-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500/50 focus:bg-white/10 resize-none max-h-32 min-h-[50px] font-serif"
                        rows={1}
                    />
                </div>

                <button 
                    onClick={() => handleSendMessage()} 
                    disabled={(!inputMessage.trim() && !attachedFile) || isLoading}
                    className={`p-3 rounded-full transition-all ${(!inputMessage.trim() && !attachedFile) || isLoading ? 'bg-white/5 text-gray-600 cursor-not-allowed' : 'bg-purple-600 hover:bg-purple-500 text-white shadow-[0_0_15px_rgba(147,51,234,0.3)]'}`}
                >
                   <Play className="w-5 h-5 transform scale-x-[-1]" />
                </button>
             </div>
             <div className="flex gap-2 mt-3 overflow-x-auto pb-2 no-scrollbar">
                {['راجع يومي', 'اقترح لي مهام', 'حمسني!'].map((quick, idx) => (
                    <button key={idx} onClick={() => { setInputMessage(quick); setTimeout(() => handleSendMessage(quick), 100); }} className="px-4 py-2 glass-card border-white/5 rounded-xl text-xs text-gray-300 hover:text-white hover:border-purple-500/30 whitespace-nowrap transition-all">
                        {quick}
                    </button>
                ))}
            </div>
          </div>
        </div>
    );
});

const ReviewView = memo(({ codeToReview, setCodeToReview, reviewCode, isLoading, reviewResult }: ReviewViewProps) => (
    <div className="p-5 space-y-6 pb-24 h-full overflow-y-auto no-scrollbar">
        <h3 className="text-2xl font-serif font-bold text-white flex items-center gap-2">
            <Code className="w-6 h-6 text-purple-400" />
