                  // Save this initial welcome to Supabase to keep consistency
                  await supabase.from('chat_logs').insert({ user_id: session.user.id, role: 'ai', text: initialAiWelcome.text });
                } else {
                  setMessages(loadedMessages);
                }
            }
        };
