          const goals = JSON.parse(result.text || '[]');

          if (session?.user) {
              const { data } = await supabase.from('goals').insert(goals.map((g: any) => ({
                  user_id: session.user.id,
                  title: g.title,
                  deadline: g.deadline,
                  roadmap: g.roadmap
              }))).select();

              if (data) {
                  setMonthlyGoals(prev => [...prev, ...data.map((g: any) => ({
                      id: g.id, 
                      title: g.title, 
                      deadline: g.deadline, 
                      roadmap: g.roadmap
                  }))]);
              }
          }

      } catch (e) {
          console.error(e);
      } finally {
          setIsLoading(false);
