const AICoachPro = () => {
  const [currentUser, setCurrentUser] = useState<ZBUserProfile | null>(null);
  const [currentView, setCurrentView] = useState('daily');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Data State
  const [dailySchedule, setDailySchedule] = useState<DailyScheduleItem[]>([]);
  const [monthlyGoals, setMonthlyGoals] = useState<MonthlyGoal[]>([]);
  const [pointsAndStreak, setPointsAndStreak] = useState({ points: 0, streak: 0 });
  const [achievements, setAchievements] = useState<Achievement[]>(initialAchievementsData);

  const [activePomodoroTask, setActivePomodoroTask] = useState<DailyScheduleItem | null>(null);
  const [pomodoroTimeLeft, setPomodoroTimeLeft] = useState(25 * 60);
  const [pomodoroPhase, setPomodoroPhase] = useState<'work' | 'break'>('work');
  const [isPomodoroRunning, setIsPomodoroRunning] = useState(false);
  const [pomodoroSessions, setPomodoroSessions] = useState(0);

  const [suggestedTasks, setSuggestedTasks] = useState<SuggestedTask[]>([]);

  const [currentTime, setCurrentTime] = useState(new Date());
  const [notifications, setNotifications] = useState<{ id: number; message: string; type: string; }[]>([]);
  const [codeToReview, setCodeToReview] = useState('');
  const [reviewResult, setReviewResult] = useState<ReviewResult | null>(null);
  const [showCompletedTasks, setShowCompletedTasks] = useState(false); 
  const [attachedFile, setAttachedFile] = useState<{data: string; mimeType: string;} | null>(null);
  const [reminderTask, setReminderTask] = useState<DailyScheduleItem | null>(null);
  const [editingTask, setEditingTask] = useState<DailyScheduleItem | null>(null);
  const [showWelcome, setShowWelcome] = useState(false);

  // Storage Helper
  const getStorageKey = (key: string) => `aicoach_${currentUser?.id}_${key}`;

  // Initial Check
  useEffect(() => {
    const savedUser = localStorage.getItem('aicoach_current_user');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
    }
  }, []);

  // Load User Data when user logs in
  useEffect(() => {
    if (currentUser) {
      const tasks = localStorage.getItem(getStorageKey('tasks'));
      if (tasks) setDailySchedule(JSON.parse(tasks));

      const goals = localStorage.getItem(getStorageKey('goals'));
      if (goals) setMonthlyGoals(JSON.parse(goals));

      const chat = localStorage.getItem(getStorageKey('chat'));
      if (chat) setMessages(JSON.parse(chat));

      const stats = localStorage.getItem(getStorageKey('stats'));
      if (stats) setPointsAndStreak(JSON.parse(stats));
    }
  }, [currentUser]);

  // Persist data
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem(getStorageKey('tasks'), JSON.stringify(dailySchedule));
      localStorage.setItem(getStorageKey('goals'), JSON.stringify(monthlyGoals));
      localStorage.setItem(getStorageKey('chat'), JSON.stringify(messages));
      localStorage.setItem(getStorageKey('stats'), JSON.stringify(pointsAndStreak));
    }
  }, [dailySchedule, monthlyGoals, messages, pointsAndStreak, currentUser]);

  const taskCategories: TaskCategory[] = [
      {
        id: 'worship', name: 'عبادة وروحانيات', icon: Sparkles, image: "https://images.unsplash.com/photo-1542816417-0983c9ad53?q=80&w=2940",
        tasks: [
          { id: 'w1', title: 'صلاة الفجر', duration: 15, type: 'prayer', icon: '🕌', category: 'worship' },
          { id: 'w5', title: 'صلاة الظهر', duration: 15, type: 'prayer', icon: '🕌', category: 'worship' },
          { id: 'w6', title: 'صلاة العصر', duration: 15, type: 'prayer', icon: '🕌', category: 'worship' },
          { id: 'w7', title: 'صلاة المغرب', duration: 15, type: 'prayer', icon: '🕌', category: 'worship' },
          { id: 'w8', title: 'صلاة العشاء', duration: 15, type: 'prayer', icon: '🕌', category: 'worship' },
          { id: 'w2', title: 'قراءة قرآن', duration: 20, type: 'habit', icon: '📖', category: 'worship' },
          { id: 'w3', title: 'أذكار الصباح والمساء', duration: 10, type: 'habit', icon: '📿', category: 'worship' },
        ]
      },
      {
        id: 'health', name: 'صحة ولياقة', icon: Heart, image: "https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?q=80&w=2940",
        tasks: [
          { id: 'h1', title: 'شرب ماء', duration: 5, type: 'habit', icon: '💧', category: 'health' },
          { id: 'h2', title: 'تمرين سريع', duration: 15, type: 'habit', icon: '💪', category: 'health' },
          { id: 'h3', title: 'وجبة صحية', duration: 20, type: 'habit', icon: '🥗', category: 'health' },
          { id: 'h4', title: 'تأمل', duration: 10, type: 'habit', icon: '🧘', category: 'health' },
        ]
      },
      {
        id: 'work', name: 'العمل والإنتاجية', icon: Briefcase, image: "https://images.unsplash.com/photo-1497215728101-856f4ea42174?q=80&w=2940",
        tasks: [
            { id: 'p1', title: 'جلسة عمل مركز', duration: 90, type: 'task', icon: '🎯', category: 'work' },
            { id: 'p2', title: 'فحص البريد', duration: 15, type: 'task', icon: '📧', category: 'work' },
            { id: 'p3', title: 'تخطيط اليوم', duration: 10, type: 'habit', icon: '📝', category: 'work' },
        ]
      },
      {
        id: 'learning', name: 'التعلم والتطوير', icon: BookOpen, image: "https://images.unsplash.com/photo-1501504905252-473c47e087f8?q=80&w=2874",
        tasks: [
            { id: 'l1', title: 'قراءة', duration: 20, type: 'habit', icon: '📚', category: 'learning' },
            { id: 'l2', title: 'دورة تعليمية', duration: 45, type: 'task', icon: '💻', category: 'learning' },
        ]
      }
    ];

  useEffect(() => {
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  const addNotification = useCallback((message: string, type = 'info') => {
    const id = Date.now();
    setNotifications(prev => [{ id, message, type }, ...prev].slice(0, 5));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 4000);
  }, []);

  // AI Client Ref
  const aiClient = useRef<GoogleGenAI | null>(null);
  const chatSession = useRef<any>(null);

  const taskSuggestionTool: FunctionDeclaration = {
      name: 'suggest_tasks',
      description: 'Suggest adding new tasks to the user\'s schedule based on their request or context. Can include subtasks for breakdown.',
      parameters: {
          type: Type.OBJECT,
          properties: {
              tasks: {
                  type: Type.ARRAY,
                  items: {
                      type: Type.OBJECT,
                      properties: {
                          title: { type: Type.STRING, description: "Task title in Arabic" },
                          time: { type: Type.STRING, description: "HH:MM format" },
                          duration: { type: Type.NUMBER, description: "Duration in minutes" },
                          category: { type: Type.STRING, enum: ['work', 'learning', 'health', 'worship', 'other'] },
                          subTasks: {
                            type: Type.ARRAY,
                            items: {
                              type: Type.OBJECT,
                              properties: {
                                title: { type: Type.STRING, description: "Subtask title" },
                                completed: { type: Type.BOOLEAN, description: "Completion status (default false)" }
                              },
                              required: ['title']
                            }
                          }
                      },
                      required: ['title', 'time', 'duration']
                  }
              }
          },
          required: ['tasks']
      }
  };

  useEffect(() => {
    if (!currentUser) return;

      aiClient.current = new GoogleGenAI({ apiKey: process.env.API_KEY });
      chatSession.current = aiClient.current.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
              systemInstruction: `دورك:
- أنت مدرب مهني (Career Instructor) ومساعد ذكي متخصص في تطوير المسار الوظيفي والإنتاجية وتطوير الذات.
- هدفك هو مساعدة المستخدم على تحقيق التوازن بين حياته المهنية والشخصية والنمو في مجاله.
- جدولة المهام بذكاء، مع تقدير الوقت اللازم لكل مهمة.
- تقسيم المهام الكبيرة إلى مهام فرعية أصغر قابلة للتنفيذ (subTasks).
- تحفيز المستخدم بأسلوب مصري ودود ("يا بطل"، "عاش"، "كمل"، "يا وحش").
- استنتج المهام من سياق الكلام واقترح إضافتها فوراً.
- اسأل دائماً عن تطورات الكارير واللايف ستايل لتقديم نصائح مخصصة.
- استخدم الأداة 'suggest_tasks' فوراً عند الحاجة لإضافة مهام.
`,
              tools: [{ functionDeclarations: [taskSuggestionTool] }]
          }
      });

      // Send initial greeting if chat is empty
      const chatData = localStorage.getItem(getStorageKey('chat'));
      if (!chatData || JSON.parse(chatData).length === 0) {
        const welcomeText = `أهلاً بك يا ${currentUser.name || 'بطل'}! أنا مساعدك الشخصي والـ Career Instructor الخاص بك. 🚀\n\nأنا هنا عشان أساعدك مش بس في تنظيم يومك، لكن كمان في بناء مسار مهني ناجح وتطوير مهاراتك بذكاء.\n\nعشان أقدر أبدأ معاك صح، محتاج أعرف منك حاجتين:\n1. إيه هو الـ Career أو المجال اللي شغال فيه أو حابب توصله؟\n2. إيه طبيعة الـ Lifestyle بتاعك دلوقتي (طالب، موظف، فريلانسر..)؟\n\nأنا جاهز أسمعك ونبدأ نخطط سوا!`;
        setMessages([{ role: 'ai', text: welcomeText, timestamp: new Date() }]);
      }
  }, [currentUser]);

  const handleSendMessage = async (msg?: string) => {
      const text = msg || inputMessage;
      if ((!text.trim() && !attachedFile) || !currentUser) return;

      const userMsg: Message = { role: 'user', text, timestamp: new Date(), attachment: attachedFile?.data };
      setMessages(prev => [...prev, userMsg]);
      setInputMessage('');
      setAttachedFile(null);
      setIsLoading(true);

      try {
          if (!aiClient.current || !chatSession.current) throw new Error("AI not initialized");

          const todayTasks = dailySchedule.map(t => `- [${t.completed ? 'x' : ' '}] ${t.time} ${t.title} (${t.duration}m)`).join('\n');
          const systemContext = `اسم المستخدم: ${currentUser.name}\nميعاد الصحيان: ${currentUser.wakeTime}\nميعاد النوم: ${currentUser.sleepTime}\nأنت تعمل كـ Career Instructor.`;

          const enrichedPrompt = `[System Context]\n${systemContext}\n\n[Current State]\nToday's Tasks:\n${todayTasks || "No tasks yet."}\n\n[User Message]\n${text}`;

          let responseText = "";

          if (attachedFile) {
              const result = await aiClient.current.models.generateContent({
                  model: 'gemini-3-flash-preview',
                  contents: {
                      parts: [
                          { inlineData: { mimeType: attachedFile.mimeType, data: attachedFile.data.split(',')[1] } },
                          { text: enrichedPrompt }
                      ]
                  }
              });
              responseText = result.text || '';
          } else {
             const result = await chatSession.current.sendMessage({ message: enrichedPrompt });

             if (result.functionCalls && result.functionCalls.length > 0) {
                 for (const call of result.functionCalls) {
                     if (call.name === 'suggest_tasks') {
                         const args = call.args as any;
                         if (args.tasks && Array.isArray(args.tasks)) {
                             setSuggestedTasks(args.tasks.map((t: any, i: number) => ({
                                 ...t, 
                                 id: `sug-${Date.now()}-${i}`, 
                                 subTasks: t.subTasks || []
                             })));

                             const toolResponse = await chatSession.current.sendMessage({
                                 message: [{
                                     functionResponse: {
                                         name: call.name,
                                         response: { result: "Tasks presented to user for confirmation." }
                                     }
                                 }]
                             });
                             responseText = toolResponse.text || "تمام، جهزتلك المهام دي، إيه رأيك؟ 👇";
                         }
                     }
                 }
             } else {
                 responseText = result.text || '';
             }
          }

          setMessages(prev => [...prev, { role: 'ai', text: responseText, timestamp: new Date() }]);

      } catch (error) {
          console.error(error);
          setMessages(prev => [...prev, { role: 'ai', text: "معلش حصلت مشكلة صغيرة، ممكن تحاول تاني؟ 😅", timestamp: new Date() }]);
      } finally {
          setIsLoading(false);
      }
  };

  const startPomodoro = (task: DailyScheduleItem) => {
      setActivePomodoroTask(task);
      setPomodoroTimeLeft(task.duration * 60);
      setPomodoroPhase('work');
      setIsPomodoroRunning(true);
      setPomodoroSessions(0);
  };

  const togglePomodoro = () => setIsPomodoroRunning(prev => !prev);
  const stopPomodoro = () => { setIsPomodoroRunning(false); setActivePomodoroTask(null); };

  const formatPomodoroTime = (seconds: number) => {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  useEffect(() => {
    let interval: number;
    if (isPomodoroRunning && pomodoroTimeLeft > 0) {
      interval = window.setInterval(() => setPomodoroTimeLeft(t => t - 1), 1000);
    } else if (isPomodoroRunning && pomodoroTimeLeft === 0) {
        if (pomodoroPhase === 'work') {
            const sessions = pomodoroSessions + 1;
            setPomodoroSessions(sessions);
            setPomodoroPhase('break');
            setPomodoroTimeLeft(sessions % 4 === 0 ? 900 : 300);
            addNotification("عاش يا بطل! وقت الراحة ☕️", 'success');
        } else {
            setPomodoroPhase('work');
            setPomodoroTimeLeft(activePomodoroTask ? activePomodoroTask.duration * 60 : 1500);
            addNotification("يلا نرجع للتركيز! 💪", 'info');
        }
    }
    return () => clearInterval(interval);
  }, [isPomodoroRunning, pomodoroTimeLeft, pomodoroPhase]);

  const toggleScheduleItem = (id: number) => {
      setDailySchedule(prev => prev.map(t => {
          if (t.id === id) {
              const newStatus = !t.completed;
              if (newStatus) setPointsAndStreak(s => ({ ...s, points: s.points + 10 }));
              return { ...t, completed: newStatus };
          }
          return t;
      }));
  };

  const deleteScheduleItem = (id: number) => {
      setDailySchedule(prev => prev.filter(t => t.id !== id));
  };

  const toggleSubTask = (taskId: number, subId: number) => {
      setDailySchedule(prev => prev.map(t => {
          if (t.id === taskId && t.subTasks) {
              return { ...t, subTasks: t.subTasks.map(s => s.id === subId ? { ...s, completed: !s.completed } : s) };
          }
          return t;
      }));
  };

  const handleAddTaskFromTemplate = (template: TaskTemplate) => {
      const newTask: DailyScheduleItem = {
          id: Date.now(),
          title: template.title,
          time: new Date().toLocaleTimeString('en-US', {hour12: false, hour: '2-digit', minute:'2-digit'}),
          duration: template.duration,
          type: template.type,
          category: template.category,
          completed: false,
          isFixed: false,
          subTasks: []
      };
      setDailySchedule(prev => [...prev, newTask].sort((a,b) => a.time.localeCompare(b.time)));
      addNotification("تمت الإضافة للجدول ✅", "success");
  };

  const reviewCode = async () => {
      if (!codeToReview || !aiClient.current) return;
      setIsLoading(true);
      try {
          const result = await aiClient.current.models.generateContent({
              model: 'gemini-3-pro-preview',
              contents: `Review this code. Return JSON: { "type": "success|error", "message": "summary", "score": 0-100, "errors": [{"line": 1, "message": "msg", "severity": "error"}], "suggestions": ["..."] }\nCode:\n${codeToReview}`,
              config: { responseMimeType: 'application/json' }
          });
          setReviewResult(JSON.parse(result.text || '{}'));
      } catch (e) {
          console.error(e);
          setReviewResult({ type: 'error', message: 'فشل التحليل', score: 0, errors: [], suggestions: [] });
      } finally {
          setIsLoading(false);
      }
  };

  const generateLongTermGoals = async () => {
      if (!aiClient.current || !currentUser) return;
      setIsLoading(true);
      try {
          const result = await aiClient.current.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: `Based on user profile: ${JSON.stringify(currentUser)} and schedule: ${JSON.stringify(dailySchedule)}, suggest 3 monthly goals. Return JSON array: [{ "title": "Goal", "deadline": "YYYY-MM-DD", "roadmap": [{"title": "Step 1", "completed": false}] }]`,
              config: { responseMimeType: 'application/json' }
          });
          const goals = JSON.parse(result.text || '[]').map((g: any, i: number) => ({ ...g, id: Date.now() + i }));
          setMonthlyGoals(prev => [...prev, ...goals]);
      } catch (e) {
          console.error(e);
      } finally {
          setIsLoading(false);
      }
  };

  const chatEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  if (!currentUser) {
      return (
        <div className="h-screen flex flex-col bg-[#0f0c29] text-white font-sans overflow-hidden">
            <div className="fixed top-4 left-0 right-0 flex flex-col items-center gap-2 z-[100] pointer-events-none">
                {notifications.map(n => (
                    <div key={n.id} className={`glass-card px-6 py-3 rounded-full text-sm font-bold shadow-lg animate-in slide-in-from-top-4 fade-in duration-300 pointer-events-auto border ${n.type === 'success' ? 'border-green-500/30 text-green-300' : (n.type === 'error' ? 'border-red-500/30 text-red-300' : 'border-blue-500/30 text-blue-300')}`}>
                        {n.message}
                    </div>
                ))}
            </div>
            <AuthView 
                onLogin={(email) => {
                  const id = btoa(email);
                  const user: ZBUserProfile = {
                    id,
                    email,
                    name: email.split('@')[0],
                    wakeTime: '07:00',
                    sleepTime: '23:00',
                    isOnboarded: false
                  };
                  // check if already onboarded in localStorage
                  const existingProfile = localStorage.getItem(`aicoach_${id}_profile`);
                  if (existingProfile) {
                    const profile = JSON.parse(existingProfile);
                    setCurrentUser(profile);
                    localStorage.setItem('aicoach_current_user', existingProfile);
                  } else {
                    setCurrentUser(user);
                    localStorage.setItem('aicoach_current_user', JSON.stringify(user));
                  }
                }} 
                addNotification={addNotification} 
            />
        </div>
      );
  }

  if (!currentUser.isOnboarded) {
      return (
        <div className="h-screen flex flex-col bg-[#0f0c29] text-white font-sans overflow-hidden">
            <OnboardingView 
                initialName={currentUser.name}
                onComplete={async ({ name, wakeTime, sleepTime }) => {
                    const onboardedUser = { ...currentUser, name, wakeTime, sleepTime, isOnboarded: true };
                    setCurrentUser(onboardedUser);
                    localStorage.setItem('aicoach_current_user', JSON.stringify(onboardedUser));
                    localStorage.setItem(getStorageKey('profile'), JSON.stringify(onboardedUser));
                    setShowWelcome(true);
                }}
            />
        </div>
      );
  }

  return (
    <div className="h-screen flex flex-col bg-[#0f0c29] text-white font-sans overflow-hidden">
        <div className="fixed top-4 left-0 right-0 flex flex-col items-center gap-2 z-[100] pointer-events-none">
            {notifications.map(n => (
                <div key={n.id} className={`glass-card px-6 py-3 rounded-full text-sm font-bold shadow-lg animate-in slide-in-from-top-4 fade-in duration-300 pointer-events-auto border ${n.type === 'success' ? 'border-green-500/30 text-green-300' : 'border-blue-500/30 text-blue-300'}`}>
                    {n.message}
                </div>
            ))}
        </div>

        {showWelcome && (
            <WelcomeView 
                userName={currentUser.name} 
                onStart={() => setShowWelcome(false)} 
            />
        )}

        <PomodoroTimer 
            activePomodoroTask={activePomodoroTask} 
            isPomodoroRunning={isPomodoroRunning}
            pomodoroPhase={pomodoroPhase}
            pomodoroTimeLeft={pomodoroTimeLeft}
            pomodoroSessions={pomodoroSessions}
            togglePomodoro={togglePomodoro}
            stopPomodoro={stopPomodoro}
            formatPomodoroTime={formatPomodoroTime}
        />

        <TaskModal 
            task={editingTask} 
            onSave={(task) => {
                if (task.id === 0) {
                    const newTask = { ...task, id: Date.now() };
                    setDailySchedule(prev => [...prev, newTask].sort((a,b) => a.time.localeCompare(b.time)));
                    addNotification("تم إنشاء المهمة بنجاح ✨", "success");
                } else {
                    setDailySchedule(prev => prev.map(t => t.id === task.id ? task : t).sort((a,b) => a.time.localeCompare(b.time)));
                    addNotification("تم حفظ التعديلات ✅", "success");
                }
                setEditingTask(null);
            }} 
            onCancel={() => setEditingTask(null)} 
        />

        <ReminderModal 
            task={reminderTask} 
            onSet={(m) => {
                if (reminderTask) {
                    setDailySchedule(prev => prev.map(t => t.id === reminderTask.id ? { ...t, reminderMinutes: m } : t));
                    addNotification(m ? "تم ضبط المنبه ⏰" : "تم إلغاء المنبه 🔕");
                }
                setReminderTask(null);
            }} 
            onCancel={() => setReminderTask(null)} 
        />

        <div className="flex-1 overflow-hidden relative">
            {currentView === 'daily' && <DailyView 
                currentTime={currentTime}
                stats={pointsAndStreak}
                dailySchedule={dailySchedule}
                toggleScheduleItem={toggleScheduleItem}
                deleteScheduleItem={deleteScheduleItem}
                toggleSubTask={toggleSubTask}
                activePomodoroTask={activePomodoroTask}
                startPomodoro={startPomodoro}
                showCompletedTasks={showCompletedTasks}
                setShowCompletedTasks={setShowCompletedTasks}
                queryTaskDetails={async (task) => { setCurrentView('chat'); handleSendMessage(`ممكن تفاصيل أكتر عن مهمة "${task.title}"؟`); }}
                taskCategories={taskCategories}
                handleAddTaskFromTemplate={handleAddTaskFromTemplate}
                setReminderTask={setReminderTask}
                onAddTask={() => setEditingTask({ id: 0, title: '', time: '09:00', duration: 30, type: 'task', completed: false, isFixed: false, subTasks: [] })}
                onEditTask={setEditingTask}
            />}
            {currentView === 'chat' && <ChatView 
                messages={messages}
                suggestedTasks={suggestedTasks}
                confirmTask={(id) => {
                    const task = suggestedTasks.find(t => t.id === id);
                    if (task) {
                        setDailySchedule(prev => [...prev, { ...task, id: Date.now(), type: 'task', completed: false, isFixed: false }].sort((a,b) => a.time.localeCompare(b.time)));
                        setSuggestedTasks(prev => prev.filter(t => t.id !== id));
                        addNotification("تمت الإضافة للجدول 👍", "success");
                    }
                }}
                confirmAllTasks={() => {
                    const newTasks = suggestedTasks.map((t, i) => ({ ...t, id: Date.now() + i, type: 'task', completed: false, isFixed: false }));
                    setDailySchedule(prev => [...prev, ...newTasks].sort((a,b) => a.time.localeCompare(b.time)));
                    setSuggestedTasks([]);
                    addNotification("تم إضافة كل الاقتراحات 🚀", "success");
                }}
                rejectTask={(id) => setSuggestedTasks(prev => prev.filter(t => t.id !== id))}
                rejectAllTasks={() => setSuggestedTasks([])}
                isLoading={isLoading}
                chatEndRef={chatEndRef}
                inputRef={inputRef}
                inputMessage={inputMessage}
                setInputMessage={setInputMessage}
                handleSendMessage={handleSendMessage}
                attachedFile={attachedFile}
                setAttachedFile={setAttachedFile}
            />}
            {currentView === 'goals' && <GoalsView 
                monthlyGoals={monthlyGoals}
                isLoading={isLoading}
                generateLongTermGoals={generateLongTermGoals}
                toggleGoalStep={(gid, idx) => {
                    setMonthlyGoals(prev => prev.map(g => g.id === gid ? { ...g, roadmap: g.roadmap.map((s, i) => i === idx ? { ...s, completed: !s.completed } : s) } : g));
                }}
                deleteGoal={(id) => setMonthlyGoals(prev => prev.filter(g => g.id !== id))}
            />}
            {currentView === 'progress' && <ProgressView 
                userProfile={currentUser}
                stats={pointsAndStreak}
                dailySchedule={dailySchedule}
                achievements={achievements}
                onSignOut={() => {
                  localStorage.removeItem('aicoach_current_user');
                  setCurrentUser(null);
                }}
            />}
            {currentView === 'review' && <ReviewView 
                codeToReview={codeToReview}
                setCodeToReview={setCodeToReview}
                reviewCode={reviewCode}
                isLoading={isLoading}
                reviewResult={reviewResult}
            />}
        </div>

        <div className="glass-panel border-t border-white/10 relative z-50 pb-safe">
            <div className="flex justify-around items-center p-2">
                {[
                    { id: 'chat', icon: MessageCircle, label: 'المحادثة' },
                    { id: 'daily', icon: Calendar, label: 'يومي' },
                    { id: 'goals', icon: Flag, label: 'أهدافي' },
                    { id: 'progress', icon: TrendingUp, label: 'إنجازي' },
                    { id: 'review', icon: Code, label: 'مطور' },
                ].map((item) => {
                    const isActive = currentView === item.id;
                    return (
                        <button 
                            key={item.id}
                            onClick={() => setCurrentView(item.id)}
                            className={`flex flex-col items-center gap-1 p-2 rounded-2xl transition-all duration-300 ${isActive ? 'text-purple-300 -translate-y-2' : 'text-gray-500 hover:text-gray-300'}`}
                        >
                            <div className={`p-2 rounded-xl transition-all ${isActive ? 'bg-purple-500/20 shadow-[0_0_15px_rgba(168,85,247,0.3)]' : 'bg-transparent'}`}>
                                <item.icon className={`w-6 h-6 ${isActive ? 'fill-current' : ''}`} />
                            </div>
                            <span className={`text-[10px] font-bold ${isActive ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>{item.label}</span>
                        </button>
                    )
                })}
            </div>
        </div>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root') as HTMLElement);
root.render(<AICoachPro />);

