                      className={`mt-1.5 w-7 h-7 rounded-xl border-2 flex items-center justify-center flex-shrink-0 transition-all duration-300 ${
                        item.completed 
                          ? 'bg-gradient-to-br from-green-400 to-emerald-600 border-transparent shadow-[0_0_15px_rgba(34,197,94,0.4)]'
                          : isNext
                          ? 'border-purple-400 hover:bg-purple-400/20'
                          : 'border-gray-600 hover:border-gray-400'
                      }`}
                    >
                      {item.completed && <Check className="w-4 h-4 text-white stroke-[3]" />}
                    </button>

                    <div className="flex-1 min-w-0 pt-0.5">
                      <div className="flex items-center gap-2 mb-1.5" onClick={() => toggleExpand(item.id)}>
