                <h3 className="text-xl font-bold font-serif text-white mb-2">تذكير للمهمة</h3>
                <p className="text-purple-200 mb-6">{task.title}</p>
                <div className="grid grid-cols-2 gap-3 mb-4">
                    {[5, 10, 15, 30].map(m => (
                        <button key={m} onClick={() => onSet(m)} className={`py-2 rounded-xl border border-white/10 hover:bg-purple-600 hover:border-purple-500 transition-colors ${task.reminderMinutes === m ? 'bg-purple-600' : 'bg-white/5'}`}>{m} دقيقة</button>
                    ))}
                </div>
                <div className="flex gap-2 mb-4">
                     <input type="number" value={custom} onChange={e => setCustom(e.target.value)} placeholder="دقيقة.." className="flex-1 bg-black/30 border border-white/10 rounded-xl p-2 text-center text-white"/>
                     <button onClick={() => onSet(Number(custom))} disabled={!custom} className="px-4 bg-purple-600 rounded-xl text-white">تم</button>
                </div>
                {task.reminderMinutes && <button onClick={() => onSet(undefined)} className="text-sm text-red-400 underline">إلغاء التذكير</button>}
                <button onClick={onCancel} className="absolute top-4 right-4 text-gray-400"><X className="w-5 h-5" /></button>
            </div>
        </div>
    );
});

